# 使用 dataclass 替代 NamedTuple，提取公共基类

from dataclasses import dataclass
from typing import Optional
import torch

@dataclass
class BaseMLAPreprocessResult:
    """Base class with common fields for MLA preprocess results."""
    query: torch.Tensor
    key: torch.Tensor
    value: torch.Tensor
    attn_mask: Optional[torch.Tensor]

@dataclass
class PrefillMLAPreprocessResult(BaseMLAPreprocessResult):
    """Prefill MLA preprocess result."""
    seq_len: int

@dataclass
class DecodeMLAPreprocessResult(BaseMLAPreprocessResult):
    """Decode MLA preprocess result."""
    # 继承公共字段，不再重复定义
    pass
